import{_ as o,C as i,o as n,c as r,a2 as a,E as d}from"./chunks/framework.CjcFWkVi.js";const c=JSON.parse('{"title":"Verzie tejto dokumentácie","description":"Ktoré vydanie Nette API táto dokumentácia opisuje, ako sa označujú funkcie „Od verzie 3.6.0“ a kde je dokumentácia pre 4.x a staršiu radu 2.x.","frontmatter":{"title":"Verzie tejto dokumentácie","description":"Ktoré vydanie Nette API táto dokumentácia opisuje, ako sa označujú funkcie „Od verzie 3.6.0“ a kde je dokumentácia pre 4.x a staršiu radu 2.x."},"headers":[],"relativePath":"sk/guide/versioning.md","filePath":"sk/guide/versioning.md","lastUpdated":1793352022000}'),s={name:"sk/guide/versioning.md"};function u(m,e,h,k,v,l){const t=i("Diagram");return n(),r("div",null,[e[0]||(e[0]=a('<h1 id="verzie-tejto-dokumentacie" tabindex="-1">Verzie tejto dokumentácie <a class="header-anchor" href="#verzie-tejto-dokumentacie" aria-label="Permalink to &quot;Verzie tejto dokumentácie&quot;">​</a></h1><p>Tento web opisuje <strong>3.x</strong>, aktuálnu radu vydaní; posledné vydanie je 3.6.0. Nainštalujete ho cez <code>composer require tomaj/nette-api</code>. Potrebuje PHP 8.3 alebo novšie. Vetva <code>master</code> (<code>dev-master</code>) je 4.0 vo vývoji a potrebuje PHP 8.4 alebo novšie; jej nespätne kompatibilné zmeny sú v <a href="https://github.com/tomaj/nette-api/blob/master/UPGRADE-4.0.md" target="_blank" rel="noreferrer">UPGRADE-4.0.md</a>.</p>',2)),d(t,{name:"versioning-1",alt:"Dnes je 3.x v koreni; keď vyjde 4.x, prevezme koreň a 3.x sa presunie do /3.x/"}),e[1]||(e[1]=a('<table tabindex="0"><thead><tr><th>Rada</th><th>Kde</th></tr></thead><tbody><tr><td>3.x</td><td>tento web, v koreni</td></tr><tr><td>4.x</td><td>po vydaní prevezme koreň; 3.x sa presunie do <code>/3.x/</code></td></tr><tr><td>2.x a staršie</td><td><a href="https://github.com/tomaj/nette-api/tree/2.13.0" target="_blank" rel="noreferrer">README verzie 2.13.0</a> na GitHube</td></tr></tbody></table><p><a href="/nette-api/sk/changelog.html">Changelog</a> obsahuje každé vydanie, <a href="/nette-api/sk/upgrade.html">návod na upgrade</a> nekompatibilné zmeny.</p><h2 id="caste-otazky" tabindex="-1">Časté otázky <a class="header-anchor" href="#caste-otazky" aria-label="Permalink to &quot;Časté otázky&quot;">​</a></h2><h3 id="ako-zistim-ktoru-verziu-mam" tabindex="-1">Ako zistím, ktorú verziu mám? <a class="header-anchor" href="#ako-zistim-ktoru-verziu-mam" aria-label="Permalink to &quot;Ako zistím, ktorú verziu mám?&quot;">​</a></h3><p><code>composer show tomaj/nette-api</code>.</p><h3 id="bude-3-x-dostavat-opravy-aj-po-4-0" tabindex="-1">Bude 3.x dostávať opravy aj po 4.0? <a class="header-anchor" href="#bude-3-x-dostavat-opravy-aj-po-4-0" aria-label="Permalink to &quot;Bude 3.x dostávať opravy aj po 4.0?&quot;">​</a></h3><p>Na GitHube je otvorený <a href="https://github.com/tomaj/nette-api/milestone/9" target="_blank" rel="noreferrer">milník 4.0.0</a> s plánovanými nekompatibilnými zmenami, napríklad odstránením nebezpečného režimu CORS <code>&#39;auto&#39;</code> a vyššou minimálnou verziou PHP. Dátum vydania zatiaľ nie je. Či bude 3.x dostávať opravy aj potom, zatiaľ nie je rozhodnuté; dnes idú opravy a novinky do 3.x a <a href="/nette-api/sk/changelog.html">changelog</a> ukazuje každé vydanie.</p><h3 id="oznacuju-stranky-novinky-novsieho-vydania" tabindex="-1">Označujú stránky novinky novšieho vydania? <a class="header-anchor" href="#oznacuju-stranky-novinky-novsieho-vydania" aria-label="Permalink to &quot;Označujú stránky novinky novšieho vydania?&quot;">​</a></h3><p>Áno, poznámka „Od verzie 3.6.0“ označuje, čo pridalo vydanie 3.6.0; staršie vydania ako 3.5.0 to nemajú, ako na stránkach <a href="/nette-api/sk/guide/cors.html">CORS</a> a <a href="/nette-api/sk/guide/logging.html">Logovanie</a>.</p><h3 id="kde-nahlasim-chybu-v-dokumentacii" tabindex="-1">Kde nahlásim chybu v dokumentácii? <a class="header-anchor" href="#kde-nahlasim-chybu-v-dokumentacii" aria-label="Permalink to &quot;Kde nahlásim chybu v dokumentácii?&quot;">​</a></h3><p>Otvorte issue alebo pull request, pozrite si <a href="/nette-api/sk/contributing.html">Prispievanie</a>.</p><h3 id="je-to-to-iste-ako-verzie-api-v-mojich-url" tabindex="-1">Je to to isté ako verzie API v mojich URL? <a class="header-anchor" href="#je-to-to-iste-ako-verzie-api-v-mojich-url" aria-label="Permalink to &quot;Je to to isté ako verzie API v mojich URL?&quot;">​</a></h3><p>Nie, tie opisujú <a href="/nette-api/sk/guide/links.html#verzie">Odkazy a verzie</a>.</p>',13))])}const j=o(s,[["render",u]]);export{c as __pageData,j as default};
